typedef float rational_t;
typedef float time_value_t;

struct _List_node_base
{
  _List_node_base* _M_next;
  _List_node_base* _M_prev;
};

template<class T>
struct _List_node : public _List_node_base
{
  T _M_data;
};

template<class T>
struct _List_iterator
{
  typedef _List_iterator<T> self;
  _List_node_base* _M_node;

  _List_iterator(_List_node_base* x) : _M_node(x) {}
  T& operator*() const { return ((_List_node<T>*) _M_node)->_M_data; }
  self& operator++() { _M_node = _M_node->_M_next; return *this; }
  bool operator!=(const self& x) const { return _M_node != x._M_node; }
};

template<class T>
class list
{
  _List_node_base _M_node;
public:
  typedef _List_iterator<T> iterator;
  iterator begin() { return iterator(_M_node._M_next); }
  iterator end() { return iterator(&_M_node); }
};

class entity;

class generic_interface
{
public:
  virtual ~generic_interface();
};

class entity_interface : public generic_interface
{
protected:
  entity *my_entity;
};

class time_interface
{
public:
  rational_t calc_time_dilation() const;
};

class entity
{
public:
  bool has_time_ifc() const;
  time_interface *time_ifc() const;
};

extern rational_t g_time_dilation;

#define ENTITY_TIME_DILATION(e)           (e->has_time_ifc() ? e->time_ifc()->calc_time_dilation() : g_time_dilation)
#define CALC_ENTITY_TIME_DILATION(a, e)   (a*ENTITY_TIME_DILATION(e))

class ai_interface : public entity_interface
{
protected:
  unsigned int flags;
  unsigned int team;
  unsigned int enemy_team;

  static list<ai_interface *> all_ai_interfaces;

public:
  enum
  {
    _AI_ACTIVE = 0x00000001
  };

  bool is_flagged(unsigned int f) const { return((flags & f) != 0); }
  bool is_active() const { return(is_flagged(_AI_ACTIVE) && my_entity != 0); }
  void frame_advance(time_value_t t);
  static void frame_advance_ai_interfaces(time_value_t t);
};

void ai_interface::frame_advance_ai_interfaces(time_value_t t)
{
  rational_t tx;
  list<ai_interface *>::iterator ai = all_ai_interfaces.begin();
  list<ai_interface *>::iterator ai_end = all_ai_interfaces.end();
  while(ai != ai_end)
  {
    if((*ai)->is_active())
    {
      tx = CALC_ENTITY_TIME_DILATION(t, (*ai)->my_entity);
      (*ai)->frame_advance(tx);
    }
    ++ai;
  }
}
